    val equipment = mapOf(
        "NEC-CAN" to listOf(EquipmentCard("矩阵操纵器", "阵营装备", "每场战斗一次，在一名己方冥工之环特工激活或反应期间可以使用。直到该次激活／反应结束，将己方冥工之环地相技师视为第四枚己方方尖碑节点标识。", "team_rules/NEC-CAN--25-阵营装备-矩阵操纵器.png", currentText=true), EquipmentCard("觉醒的方尖碑节点", "阵营装备", "展示此装备选项后掷一枚 D3。在本场战斗中，可以使用等于结果次数的 0CP“灵动方尖碑节点”交战计谋。", "team_rules/NEC-CAN--26-阵营装备-觉醒的方尖碑节点.png", currentText=true), EquipmentCard("纳米甲虫匣", "阵营装备", "每当一名己方冥工之环特工激活，其恢复至多 D3 点已损失的耐伤。", "team_rules/NEC-CAN--27-阵营装备-纳米甲虫匣.png", currentText=true), EquipmentCard("移相器", "阵营装备", "每个转折点一次，一名特工向己方冥工之环地相技师射击时，在掷防御骰步骤开始时可以使用。直到该流程结束，将“穿刺”武器规则的 X 降低 1（若有）。因此，“穿刺 1”会被忽略。", "team_rules/NEC-CAN--28-阵营装备-移相器.png", currentText=true)),
        "IMP-WS" to listOf(EquipmentCard("冰霜武器", "阵营装备", "每当一名己方狼侦察特工完全位于己方风暴内，其格斗刀（若有）拥有“致命 5+”（Lethal 5+）武器规则。", "team_rules/IMP-WS--25-阵营装备-冰霜武器.png", currentText=true), EquipmentCard("符文守护", "阵营装备", "每个转折点一次，一名特工向完全位于己方风暴内的一名己方狼侦察特工（芬里斯狼除外）射击时，在掷防御骰步骤开始时可以使用。直到该流程结束，将“穿刺”武器规则的 X 降低 1（若有）。因此，“穿刺 1”会被忽略。", "team_rules/IMP-WS--26-阵营装备-符文守护.png", currentText=true), EquipmentCard("狼牙项链", "阵营装备", "每个转折点一次，一名己方狼侦察特工（芬里斯狼除外）射击、近战或反击时，若掷出至少两枚失败，可以丢弃其中一枚，并将另一枚改为保留为普通成功。", "team_rules/IMP-WS--27-阵营装备-狼牙项链.png", currentText=true), EquipmentCard("战利品护符", "阵营装备", "每当一名完全位于己方风暴内的己方狼侦察特工（芬里斯狼除外）近战或反击，在结算攻击骰步骤中，可以使一枚普通成功对其造成的伤害减少 1。", "team_rules/IMP-WS--28-阵营装备-战利品护符.png", currentText=true)),
        "IMP-CI" to listOf(EquipmentCard("灭灵手雷", "阵营装备", "此装备允许选择两枚通用装备“功能型手雷”中的手雷，且必须都为震荡手雷。如果还正常选择了该通用装备，便不能再选择任何震荡手雷，即不能因此获得超过两枚。\n每当一名特工因己方洁天使隐伏者执行震荡手雷行动而进行震荡测试，若结果为 3+，额外对被测试的特工造成等于掷骰结果一半（向上取整）的伤害。如果其拥有灵能者（PSYKER）关键词，则改为造成等于掷骰结果的伤害。", "team_rules/IMP-CI--29-阵营装备-灭灵手雷.png", currentText=true), EquipmentCard("殉道悼歌", "阵营装备", "每场战斗一次，一名处于圣勉状态的己方洁天使隐伏者特工残废时可以使用。在结算殉道阵营规则时，可以选择另一名己方洁天使隐伏者特工，即使其不满足与残废特工的可见性或 6\" 距离要求。", "team_rules/IMP-CI--30-阵营装备-殉道悼歌.png", currentText=true), EquipmentCard("遗珍圣物", "阵营装备", "一枚攻击骰将对一名己方洁天使隐伏者特工造成伤害时，可以使用。掷一枚 D6；如果该特工处于圣勉状态，改为掷两枚。任意一枚结果为 6，便忽略该攻击骰造成的伤害。每次行动最多以此方式忽略一枚攻击骰，每场战斗最多忽略两枚。", "team_rules/IMP-CI--31-阵营装备-遗珍圣物.png", currentText=true), EquipmentCard("自动鞭笞装置", "阵营装备", "每当一名己方洁天使隐伏者特工激活，可以使用。掷一枚 D6，对其造成等于结果一半（向上取整）的伤害；结果为 4+ 时，其还进入圣勉状态。每个转折点最多通过本规则使一名己方特工进入圣勉状态。", "team_rules/IMP-CI--32-阵营装备-自动鞭笞装置.png", currentText=true))
    )
    fun teamArt(id: String): Int? = TeamMarks.resourceOrNull(id)
    val weaponRules = listOf(
